-- ADCT, comentários didáticos, lote 7 (arts. 60-A a 69), só a partir do texto no banco. Já aplicado.
update legislacao set contexto = $c$Revisão dos critérios de distribuição do Fundeb$c$, aplicacao_pratica = $a$Determina que os critérios de distribuição da complementação da União e dos fundos referidos no art. 212-A, I, da Constituição sejam revistos no sexto ano de vigência e, a partir dessa primeira revisão, periodicamente, a cada dez anos.$a$ where codigo='adct' and numero=60 and titulo='Art. 60-A' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Recursos públicos a entidades educacionais$c$, aplicacao_pratica = $a$Permite que as entidades educacionais do art. 213 e as fundações de ensino e pesquisa criadas com autorização legal, que preencham os requisitos dos incisos I e II daquele artigo e tenham recebido recursos públicos nos últimos três anos, continuem a recebê-los, salvo disposição legal em contrário.$a$ where codigo='adct' and numero=61 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Criação do SENAR$c$, aplicacao_pratica = $a$Determina que a lei crie o Serviço Nacional de Aprendizagem Rural (SENAR) nos moldes da legislação do SENAI e do SENAC, sem prejuízo das atribuições dos órgãos públicos que atuam na área.$a$ where codigo='adct' and numero=62 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Comissão do centenário da República$c$, aplicacao_pratica = $a$Criou comissão de nove membros, três de cada Poder, para promover as comemorações do centenário da proclamação da República e da promulgação da primeira Constituição republicana, com possibilidade de subcomissões. O parágrafo único atribuiu à Comissão estudos, debates e avaliações sobre a evolução política, social, econômica e cultural do País, com articulação com governos estaduais e municipais e instituições públicas e privadas. Norma de objeto já exaurido com as comemorações.$a$ where codigo='adct' and numero=63 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Edição popular da Constituição$c$, aplicacao_pratica = $a$Determina que a Imprensa Nacional e as demais gráficas públicas da União, dos Estados, do Distrito Federal e dos Municípios, da administração direta ou indireta, inclusive fundações mantidas pelo Poder Público, promovam edição popular do texto integral da Constituição, posta gratuitamente à disposição de escolas, cartórios, sindicatos, quartéis, igrejas e outras instituições representativas da comunidade, para que cada cidadão possa receber do Estado um exemplar.$a$ where codigo='adct' and numero=64 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Regulamentação do art. 220, § 4º$c$, aplicacao_pratica = $a$Fixou ao Poder Legislativo o prazo de doze meses para regulamentar o art. 220, § 4º, da Constituição.$a$ where codigo='adct' and numero=65 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Concessões de telecomunicações em vigor$c$, aplicacao_pratica = $a$Mantém as concessões de serviços públicos de telecomunicações em vigor na data da promulgação, nos termos da lei.$a$ where codigo='adct' and numero=66 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Prazo para a demarcação das terras indígenas$c$, aplicacao_pratica = $a$Fixa à União o prazo de cinco anos, a partir da promulgação da Constituição, para concluir a demarcação das terras indígenas.$a$ where codigo='adct' and numero=67 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Propriedade das terras de quilombos$c$, aplicacao_pratica = $a$Reconhece aos remanescentes das comunidades dos quilombos que estejam ocupando suas terras a propriedade definitiva, cabendo ao Estado emitir os títulos respectivos.$a$ where codigo='adct' and numero=68 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Consultorias jurídicas estaduais separadas$c$, aplicacao_pratica = $a$Permite aos Estados manter consultorias jurídicas separadas de suas Procuradorias-Gerais ou Advocacias-Gerais, desde que, na data da promulgação da Constituição, já tivessem órgãos distintos para essas funções.$a$ where codigo='adct' and numero=69 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
